#ifndef MEP_JULIA_LSP_H
#define MEP_JULIA_LSP_H

// The analysis half of mep's own Julia language server (the wire half is
// julia_lsp_server.cpp, the `mep-julia-lsp` binary; the `julia_ls` entry
// in main.cpp's kBuiltinLsp spawns it). Everything here is a pure function
// of the document text, so the whole server is testable without a client
// (julia_lsp_test.cpp). Positions are 0-based lines and 0-based byte
// columns (`positionEncoding: "utf-8"`).
//
// Generated by tools/new_language.py; nix_lsp.h is the worked example of
// every function below.

#include <memory>
#include <string>
#include <vector>

struct JuliaLspRange {
    int line = 0, col = 0, end_line = 0, end_col = 0;
};

class JuliaLspDocument;

/** @brief Parses and analyses a document; every query below runs on the result.
 *  `path` (the document's file, "" for none) is where `using Package` starts looking:
 *  the package's exports and docstrings then serve hover, completion, signature help and
 *  definitions (julia_lsp_packages.cpp). */
std::shared_ptr<const JuliaLspDocument> JuliaLspAnalyze(const std::vector<std::string> &lines,
                                                       const std::string &path = std::string());
/** @brief Tests: replaces JULIA_LOAD_PATH for package lookup (nullptr restores it) and drops the cache. */
void JuliaLspSetLoadPath(const std::vector<std::string> *entries);

// --- Diagnostics ------------------------------------------------------------------

enum class JuliaLspSeverity { Error = 1, Warning = 2, Information = 3, Hint = 4 };

struct JuliaLspDiagnostic {
    JuliaLspRange range;
    JuliaLspSeverity severity = JuliaLspSeverity::Error;
    std::string code;  // stable id: syntax-error, ...
    std::string message;
    bool unnecessary = false;  // LSP DiagnosticTag.Unnecessary
    bool deprecated = false;   // LSP DiagnosticTag.Deprecated
};

std::vector<JuliaLspDiagnostic> JuliaLspDiagnostics(const JuliaLspDocument &doc);
/** @brief Julia's own verdict on @p text, as tools/ts_grammar_diff/julia_check.jl prints it:
 *  "" when JuliaSyntax (Meta.parseall) accepts it, else its first error as `LINE:COL: message`
 *  (1-based; the column counts characters). */
std::string JuliaLspJuliaCheck(const std::string &text);
/** @brief `path:line:col: severity: message [code]`, 1-based, as `--lint` prints it. */
std::string JuliaLspFormatDiagnostic(const std::string &path, const JuliaLspDiagnostic &d);
/** @brief Whether a diagnostic makes `--lint` exit non-zero (an error or a warning). */
bool JuliaLspDiagnosticFails(const JuliaLspDiagnostic &d);

// --- Completion / hover / signature help -------------------------------------------

enum class JuliaLspKind {
    Text = 1, Method = 2, Function = 3, Field = 5, Variable = 6, Class = 7, Module = 9, Property = 10,
    Value = 12, Keyword = 14, Snippet = 15, Constant = 21, Struct = 22,
};

struct JuliaLspCompletionItem {
    std::string label;
    std::string insert_text;
    JuliaLspKind kind = JuliaLspKind::Text;
    std::string detail;
    std::string documentation;
    int replace_start = 0, replace_end = 0;  // byte columns on the request's line
};

std::vector<JuliaLspCompletionItem> JuliaLspCompletions(const JuliaLspDocument &doc, int line, int col);

struct JuliaLspHoverInfo {
    bool found = false;
    std::string text;  // markdown
    JuliaLspRange range;
};

JuliaLspHoverInfo JuliaLspHover(const JuliaLspDocument &doc, int line, int col);

struct JuliaLspSignatureHelp {
    bool found = false;
    std::string label;
    std::vector<std::string> params;  // substrings of label
    std::string documentation;
    int active_param = 0;
};

JuliaLspSignatureHelp JuliaLspSignatureAt(const JuliaLspDocument &doc, int line, int col);

// --- Navigation -------------------------------------------------------------------------

struct JuliaLspLocation {
    JuliaLspRange range;
    std::string path;  // "" = this document, else a package's file
};

std::vector<JuliaLspLocation> JuliaLspDefinition(const JuliaLspDocument &doc, int line, int col);

struct JuliaLspReference {
    JuliaLspRange range;
    bool is_definition = false;
};

std::vector<JuliaLspReference> JuliaLspReferences(const JuliaLspDocument &doc, int line, int col);

struct JuliaLspTextEdit {
    JuliaLspRange range;
    std::string new_text;
};

struct JuliaLspRenameTarget {
    bool found = false;
    JuliaLspRange range;
    std::string placeholder;
};

JuliaLspRenameTarget JuliaLspPrepareRename(const JuliaLspDocument &doc, int line, int col);
std::vector<JuliaLspTextEdit> JuliaLspRename(const JuliaLspDocument &doc, int line, int col,
                                               const std::string &new_name, std::string *error);

// --- Outline / folding --------------------------------------------------------------------

enum class JuliaLspSymbolKind {
    File = 1, Module = 2, Namespace = 3, Class = 5, Method = 6, Property = 7, Field = 8, Function = 12,
    Variable = 13, Constant = 14, String = 15, Number = 16, Boolean = 17, Array = 18, Object = 19, Key = 20,
    Null = 21,
};

struct JuliaLspSymbol {
    std::string name;
    std::string detail;
    JuliaLspSymbolKind kind = JuliaLspSymbolKind::Variable;
    JuliaLspRange range;
    JuliaLspRange sel_range;
    int parent = -1;
};

std::vector<JuliaLspSymbol> JuliaLspSymbols(const JuliaLspDocument &doc);

struct JuliaLspFold {
    int start_line = 0, end_line = 0;
    std::string kind;  // "" or "comment"
};

std::vector<JuliaLspFold> JuliaLspFolds(const JuliaLspDocument &doc);

// --- Formatting ------------------------------------------------------------------------------

/** @brief The formatter as one edit over the changed lines; none when already formatted. */
std::vector<JuliaLspTextEdit> JuliaLspFormat(const std::vector<std::string> &lines, int width, std::string *error);

#endif  // MEP_JULIA_LSP_H
